SUMMARIES = {
    'en': 'The request could not be completed. Review the original details below.',
    'fa': 'درخواست تکمیل نشد. جزئیات اصلی زیر را بررسی کنید.',
    'ps': 'غوښتنه بشپړه نه شوه. لاندې اصلي جزیات وګورئ.',
}

from .tax_error_copy import TAX_ERROR_COPY
ERROR_COPY.update(TAX_ERROR_COPY)


def language_for(request):
    """An explicit supported Accept-Language wins; otherwise use personal preference."""
    candidates=[]
    for position,part in enumerate(str(request.headers.get('Accept-Language',''))[:1000].split(',')):
        bits=part.strip().split(';');language=bits[0].split('-')[0].lower();quality=1.0
        if language not in {'fa','ps','en'}:continue
        try:
            for item in bits[1:]:
                if item.strip().startswith('q='):quality=float(item.strip()[2:])
        except ValueError:continue
        if 0<quality<=1:candidates.append((-quality,position,language))
    if candidates:return min(candidates)[2]
    user=getattr(request,'user',None)
    if user is not None and user.is_authenticated:
        from .models import UserPreference
        preference=UserPreference.objects.filter(user=user).values_list('language',flat=True).first()
        if preference in {'fa','ps','en'}:return preference
    return 'fa'

def translate_message(value,language):
    text=str(value)
    if language=='en':return text,True
    found=ERROR_COPY.get(text)
    if found:return found[0 if language=='fa' else 1],True
    # These are closed identifier templates, not arbitrary text substitutions.
    for pattern,fa,ps in [
        (r'Unconfigured account: ([A-Z][A-Z0-9_]{0,60})', 'حساب تنظیم نشده: {}', 'حساب نه دی تنظیم شوی: {}'),
        (r'Missing permission: ([a-z][a-z0-9_.]{0,80})', 'صلاحیت لازم نیست: {}', 'اړینه اجازه نشته: {}'),
    ]:
        match=re.fullmatch(pattern,text)
        if match:return (fa if language=='fa' else ps).format(match.group(1)),True
    return text,False

def localize_error_data(data,language,status):
    """Preserve original error/list/field structure; add honest completeness metadata."""
    if not isinstance(data,dict):return data
    result=dict(data);keys=[key for key in ('error','detail','details') if key in data]
    if not keys:keys=list(data) # DRF serializer errors are a field-keyed object.
    original={key:deepcopy(data[key]) for key in keys};complete=True;changed=False;visited=0
    def visit(value,depth=0):
        nonlocal complete,changed,visited
        visited+=1
        if visited>2000 or depth>12:complete=False;return value
        if isinstance(value,dict):return {key:visit(item,depth+1) for key,item in value.items()}
        if isinstance(value,(list,tuple)):return [visit(item,depth+1) for item in value]
        if isinstance(value,str):
            translated,supported=translate_message(value,language);complete=complete and supported;changed=changed or translated!=value
            if hasattr(value,'code'):
                from rest_framework.exceptions import ErrorDetail
                return ErrorDetail(translated,code=value.code)
            return translated
        return value
    for key in keys:result[key]=visit(data[key])
    result.setdefault('error_code',{400:'validation_error',401:'authentication_required',403:'permission_denied',404:'not_found',409:'record_conflict',429:'rate_limited',503:'service_unavailable'}.get(status,'request_error'))
    result['error_language']=language;result['translation_complete']=complete
    if changed:result['error_original']=original
    if not complete:result['error_summary']=SUMMARIES[language]
    return result
